-- 000788_agent_tools_coverage.up.sql
-- Agent tool catalog coverage + dead-tool drift fix.
--
-- 1. Dead-tool drift: 11 seeded ai_tools rows had no registered executor
--    handler — they appeared in the agent catalog and MCP tools/list, then
--    failed tools/call with "no handler registered". They are v1 registry
--    rows for dedicated REST endpoints (/ai/chat, /ai/assist/*,
--    /moderation/*), not agent tools. Disable + block them.
--    moderation.detect_spam additionally had NULL required_permission, which
--    would have exposed it to every agent.use holder had a handler existed;
--    pin it to moderation.content.review.
--
-- 2. tools.list / tools.read: the backing catalog now exists
--    (agentToolsRegistry over per-tool tables). Enable both; the generic
--    tools.create/update/assign_geo rows stay disabled — dedicated
--    <tool_type>.* tools own writes (§78 discrepancy resolved in favour of
--    dedicated tools).
--
-- 3. New coverage: forum Q&A (§08), comments (§49), deterministic
--    calculators (§107 CRS, §108 POF, §112 FX), and the remaining §78 tool
--    types with write-capable backing services (crs_ruleset, crs_draw,
--    pof_requirement, sop_template, sop_sample, eca_guide, eca_provider).
--    fx_rate is catalog-listed read-only (tools.read) — rates are written by
--    the mid-market fetch job, not editors.
--
-- 4. Op-level drift: baseline seeded <tool_type>.<op> rows for ops that have
--    no backing service method (resolved via WritableToolOps at writer-build
--    time). Disable them so the catalog and MCP tools/list never advertise a
--    write op that fails at call time. Re-enable only when the matching
--    service method exists.
--
-- Ref: .jeos/sections/103-ai-agent-executor.md
--      .jeos/sections/08-community-qa-forum.md
--      .jeos/sections/49-comments.md
--      .jeos/sections/107-crs-calculator.md
--      .jeos/sections/108-pof-calculator.md
--      .jeos/sections/109-eca-guide.md
--      .jeos/sections/110-sop-generator.md
--      .jeos/sections/112-fx-converter.md

BEGIN;

-- ---- 1. Dead-tool drift ----------------------------------------------------

UPDATE ai_tools
SET is_enabled = false,
    config = config || '{"is_blocked": true}'::jsonb,
    updated_at = now()
WHERE name IN (
    'chat.japabot',
    'platform.translate_string',
    'moderation.flag_content',
    'moderation.classify_severity',
    'moderation.detect_spam',
    'content.editor_assist',
    'content.generate_draft',
    'content.generate_og',
    'content.improve',
    'content.suggest_tags',
    'content.summarize'
);

UPDATE ai_tools
SET required_permission = 'moderation.content.review', updated_at = now()
WHERE name = 'moderation.detect_spam';

-- ---- 2. Generic tools catalog reads ----------------------------------------

UPDATE ai_tools
SET is_enabled = true,
    description = 'List available Japa tools and per-type record counts.',
    updated_at = now()
WHERE name = 'tools.list';

UPDATE ai_tools
SET is_enabled = true,
    description = 'Read a single tool record by tool_type + UUID.',
    updated_at = now()
WHERE name = 'tools.read';

INSERT INTO ai_tools (name, description, category, config, is_enabled, required_permission) VALUES ('forum.threads.list', 'List forum Q&A threads for a space or platform-wide.', 'agent_community', '{"function_name":"forum.threads.list","description":"List forum Q&A threads for a space or platform-wide.","handler":"forum.threads.list","parameters":{"type":"object","properties":{"space_id":{"type":"string","description":"Space UUID \u2014 omit for platform-wide"},"cursor":{"type":"string","description":"RFC3339 created_at cursor for pagination"},"limit":{"type":"integer","description":"Max results (default 25, max 100)"}},"additionalProperties":true},"writes_user_data":false,"reads_user_data":true,"requires_hitl":false,"is_blocked":false}'::jsonb, true, NULL) ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, category = EXCLUDED.category, config = EXCLUDED.config, is_enabled = EXCLUDED.is_enabled, required_permission = EXCLUDED.required_permission;
INSERT INTO ai_tools (name, description, category, config, is_enabled, required_permission) VALUES ('forum.threads.read', 'Read a single forum thread by ID or slug, optionally including replies.', 'agent_community', '{"function_name":"forum.threads.read","description":"Read a single forum thread by ID or slug, optionally including replies.","handler":"forum.threads.read","parameters":{"type":"object","properties":{"thread_id":{"type":"string","description":"Thread UUID"},"slug":{"type":"string","description":"Thread slug"},"include_replies":{"type":"boolean","description":"Also return the reply list"}},"additionalProperties":true},"writes_user_data":false,"reads_user_data":true,"requires_hitl":false,"is_blocked":false}'::jsonb, true, NULL) ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, category = EXCLUDED.category, config = EXCLUDED.config, is_enabled = EXCLUDED.is_enabled, required_permission = EXCLUDED.required_permission;
INSERT INTO ai_tools (name, description, category, config, is_enabled, required_permission) VALUES ('forum.threads.create', 'Create a forum thread (question). Requires forum.thread.create.', 'agent_community', '{"function_name":"forum.threads.create","description":"Create a forum thread (question). Requires forum.thread.create.","handler":"forum.threads.create","parameters":{"type":"object","properties":{"title":{"type":"string","description":"Thread title"},"space_id":{"type":"string","description":"Space UUID (optional)"},"content_id":{"type":"string","description":"Backing content UUID (optional)"},"slug":{"type":"string","description":"URL slug (optional)"},"body":{"description":"TipTap JSON doc or plain text"},"is_anonymous":{"type":"boolean","description":"Post anonymously"},"poll":{"type":"object","description":"Optional embedded poll {question, is_multi_select, close_at, options[]}"}},"required":["title"],"additionalProperties":true},"writes_user_data":true,"reads_user_data":false,"requires_hitl":false,"is_blocked":false}'::jsonb, true, 'forum.thread.create') ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, category = EXCLUDED.category, config = EXCLUDED.config, is_enabled = EXCLUDED.is_enabled, required_permission = EXCLUDED.required_permission;
