-- ---- 4. Op-level dead-row cleanup -----------------------------------------
-- Baseline seeded every <tool_type>.{create,update,delete,assign_geo} row
-- uniformly, but several backing services lack the matching method:
--   attestation_guide: Service exposes Create + Approve only (pathways are
--     reviewed, not edited/deleted through the tool surface).
--   embassy:           appointmentalert.Service has no DeleteEmbassy.
--   housing_guide:     Service has no delete — guides go through
--     Approve/Reject review instead.
--   mentorship_connection: bespoke writer is create-only; connection updates
--     go through match/status flows, not generic CRUD.
--   scam_report:       reports are moderated via UpdateReportStatus, not
--     deleted through the agent surface.
--   wiki_page:         assign_geo is not meaningful — pages bind to
--     destination_space_id at create; use wiki_page.update for flag changes.
-- The remaining disabled rows are all assign_geo: the resolved update
-- method's input struct has no geo-scope (*_space_id) field, so the op
-- would silently no-op. This includes types whose *entity* is geo-scoped
-- but whose update input is not (housing_guide, tax_obligation_guide,
-- visa_timeline, mutual_aid) — assign_geo lands when those inputs grow a
-- geo field.
UPDATE ai_tools
SET is_enabled = false, updated_at = now()
WHERE name IN (
    'attestation_guide.update',
    'attestation_guide.delete',
    'attestation_guide.assign_geo',
    'embassy.delete',
    'embassy.assign_geo',
    'housing_guide.delete',
    'housing_guide.assign_geo',
    'mentorship_connection.update',
    'mentorship_connection.delete',
    'mentorship_connection.assign_geo',
    'scam_report.delete',
    'wiki_page.assign_geo',
    'appointment_alert.assign_geo',
    'credential_profession.assign_geo',
    'language_test.assign_geo',
    'mutual_aid.assign_geo',
    'remittance_provider.assign_geo',
    'remittance_rate.assign_geo',
    'tax_obligation_guide.assign_geo',
    'tax_treaty_pair.assign_geo',
    'travel_provider.assign_geo',
    'visa_timeline.assign_geo'
);

COMMIT;
